# Extract max_dc bound per signed_dr
def get_max_dc_bound(sd, use_known=True):
    """Get maximum dc allowed for given signed_dr"""
    if use_known and sd in known_limits:
        return known_limits[sd]

    # Otherwise interpolate/extrapolate using peak-based model
    if sd < min(known_limits.keys()):
        # Extrapolate left (more negative)
        # Pattern: sd=-3->1, sd=-2->0, sd=-1->3
        # No clear pattern, return small safe value
        return 0 if sd % 2 == 0 else 2  # Conservative estimate
    elif sd > max(known_limits.keys()):
        # Extrapolate right (further positive) - decreasing after sd=6
        slope = (known_limits[6] - known_limits[5])  # 5-6=-1
        extra = sd - max(known_limits.keys())
        est = max(0, int(known_limits[6] + extra * slope / 1.5))
        return est
    else:
        # Interpolate between known points
        valid_sd = sorted([k for k in known_limits.keys() if k >= 0])
        idx = next(i for i, s in enumerate(valid_sd) if sd >= s)

        sd_left = valid_sd[min(idx, len(valid_sd)-2)]
        sd_right = valid_sd[min(idx+1, len(valid_sd)-1)]

        if sd_left == sd_right:
            return known_limits.get(sd_left, 5)

        val_left = known_limits[sd_left]
        val_right = known_limits[sd_right]

        # Linear interpolation with parity adjustment
        frac = (sd - sd_left) / (sd_right - sd_left)
        base = val_left + frac * (val_right - val_left)

        # Adjust for parity constraint
        if sd % 2 == base % 2:
            return max(int(base), 0)
        else:
            return max(int(base), 1 if sd % 2 != 0 else 0)

